package com.leotv.detail;

import android.view.*;
import android.widget.*;
import java.util.*;

/** Source detail XML and navigation over the existing detail controller, source paths and data. */
final class LiulangDetailLayout implements AutoCloseable {
    final TvDetailPage page;final LiulangResources res;final ViewGroup root;final LiulangHeroImage hero;final ImageView poster;
    final TextView title,facts,description,play,keep,change,more;final DetailTitleArt logo;final LiulangEpisodes episodes;
    final LinearLayout actions;final ViewGroup originalPathsParent;final int originalPathsIndex;final ViewGroup.LayoutParams originalPathsParams;final HorizontalScrollView pathsScroll;boolean extras,closed;String sourceIdentity="";SourceGateway.Detail source;MobileDetailMetadata.Result metadata;
    LiulangDetailLayout(TvDetailPage page){this.page=page;res=new LiulangResources(page.activity);root=(ViewGroup)res.inflate("activity_detail",page.content);root.setTag("leotv_liulang_detail");hero=res.find(root,"heroBg");hero.under(res.find(root,"heroBgUnder"));poster=res.find(root,"posterCardImg");title=res.find(root,"name");facts=res.find(root,"meta");description=res.find(root,"desc");play=res.find(root,"play");keep=res.find(root,"keep");change=res.find(root,"change");actions=(LinearLayout)play.getParent();
        ImageView original=res.find(root,"heroLogoImg");ViewGroup parent=(ViewGroup)original.getParent();ViewGroup.LayoutParams params=original.getLayoutParams();int index=parent.indexOfChild(original);parent.removeView(original);logo=new DetailTitleArt(res,this::titleState);logo.setAdjustViewBounds(true);logo.setMaxWidth(res.dp(720));parent.addView(logo,index,params);
        play.setOnClickListener(v->page.playButton.performClick());keep.setOnClickListener(v->{page.keepButton.performClick();kept();});change.setOnClickListener(v->page.sitePicker.selector.performClick());
        more=new TextView(res);more.setText("更多");more.setTextSize(13);more.setTextColor(android.graphics.Color.WHITE);more.setGravity(Gravity.CENTER);more.setFocusable(true);more.setFocusableInTouchMode(true);more.setPadding(res.dp(16),res.dp(6),res.dp(16),res.dp(6));more.setBackground(res.drawable("selector_detail_item"));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,res.dp(36));lp.leftMargin=res.dp(12);actions.addView(more,lp);more.setId(View.generateViewId());change.setNextFocusRightId(more.getId());more.setOnClickListener(v->extra(true));more.setContentDescription("演员、剧照、评论、推荐、追更、元数据匹配与下载");
        episodes=new LiulangEpisodes(res,root,"segment",new LiulangEpisodes.Actions(){public void play(SourceGateway.Episode episode){page.actions.play(episode);}public void flag(String value){page.selectLiulangFlag(value);sync();}public void order(boolean reverse,boolean reversePlay){page.reversed=reverse;page.reversePlay=reversePlay;page.showEpisodes();sync();}});
        originalPathsParent=(ViewGroup)page.playbackPaths.rows.getParent();originalPathsIndex=originalPathsParent.indexOfChild(page.playbackPaths.rows);originalPathsParams=page.playbackPaths.rows.getLayoutParams();pathsScroll=new HorizontalScrollView(res);pathsScroll.setHorizontalScrollBarEnabled(false);((ViewGroup)res.find(root,"flagLayout")).addView(pathsScroll,new LinearLayout.LayoutParams(-1,-2));
        page.content.addView(root,new ViewGroup.LayoutParams(-1,-1));page.scroll.setVisibility(View.GONE);page.hero.setActive(false);root.post(()->{if(!closed)play.requestFocus();});
        page.playbackPaths.rows.setVisibility(View.VISIBLE);sync();
    }
    void kept(){try{keep.setText(page.source!=null&&NativeLibrary.isKept(page.activity,page.source)?"已收藏":"收藏");}catch(ReflectiveOperationException unavailable){keep.setText("收藏");}}
    void titleState(){if(logo==null)return;logo.setVisibility(logo.ready()?View.VISIBLE:View.GONE);title.setVisibility(logo.ready()?View.GONE:View.VISIBLE);}
    void sync(){if(closed)return;SourceGateway.Detail value=page.source;MobileDetailMetadata.Result result=page.metadata;if(!android.text.TextUtils.equals(play.getText(),page.playButton.getText()))play.setText(page.playButton.getText());play.setEnabled(page.preferred!=null);
        if(value!=source||result!=metadata){source=value;metadata=result;kept();title.setText(value==null?page.title.getText():value.name);facts.setText(page.facts.getText());facts.setVisibility(View.VISIBLE);description.setText(page.synopsis.getText());description.setVisibility(View.VISIBLE);titleState();if(result!=null)logo.load(result.branding.logos,BackdropSettings.read(page.activity).proxy);
            List<String> backdrops=result==null?Collections.emptyList():result.backdropPaths;if(!backdrops.isEmpty()){res.find(root,"posterCard").setVisibility(View.GONE);hero.load(backdrops.get(0),false,null);}else if(value!=null){hero.clear();res.find(root,"posterCard").setVisibility(View.VISIBLE);NativeCspUi.homeImage(poster,value.name,value.picture);}}
        episodes.bind(value,page.selectedFlag,page.preferred,page.reversed,page.reversePlay);
        // The existing path resolver is the only owner of the provider's second-level choices.
        ViewGroup paths=page.playbackPaths.rows;ViewGroup target=extras?originalPathsParent:pathsScroll;if(paths.getParent()!=target){NativeCspUi.remove(paths);if(extras)target.addView(paths,Math.min(originalPathsIndex,target.getChildCount()),originalPathsParams);else target.addView(paths,new HorizontalScrollView.LayoutParams(-2,-2));}
    }
    void extra(boolean value){extras=value;sync();root.setVisibility(value?View.GONE:View.VISIBLE);page.scroll.setVisibility(value?View.VISIBLE:View.GONE);page.hero.setActive(value);if(value){page.playButton.requestFocus();page.scroll.scrollTo(0,0);}else{hero.active(true);sync();more.requestFocus();}}
    boolean key(KeyEvent event){if(extras){if(event.getKeyCode()==KeyEvent.KEYCODE_BACK&&!page.sitePicker.showing()&&!page.nativeEpisodes.active()&&(page.personPopup==null||!page.personPopup.showing())&&page.matchPopup==null){if(event.getAction()==KeyEvent.ACTION_UP&&!event.isCanceled())extra(false);return true;}return false;}View focused=page.activity.getCurrentFocus();int code=event.getKeyCode();if(page.sitePicker.showing()){if(code==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP&&!page.sitePicker.back())page.sitePicker.dismiss();return true;}if(code==19||code==20||code==21||code==22){if(event.getAction()==KeyEvent.ACTION_DOWN)page.sitePicker.moveFocus(code);return true;}return false;}if(code==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP&&!event.isCanceled())page.activity.finish();return true;}if(episodes.key(event,focused,play))return true;if(code==KeyEvent.KEYCODE_DPAD_DOWN&&NativeCspUi.descendant(focused,actions)){if(event.getAction()==KeyEvent.ACTION_DOWN)episodes.flags.requestFocus();return true;}return false;}
    void resume(){page.hero.setActive(extras);hero.active(true);sync();episodes.focusEpisode();}
    void pause(){hero.active(false);}
    @Override public void close(){if(closed)return;closed=true;hero.close();logo.close();NativeCspUi.releaseHomeImage(poster);NativeCspUi.remove(root);}
}
